            requiredMaterials = listOf("أسمنت بورتلاندي مقاوم للكبريتات SRC وأسمنت أبيض", "رمل حرش كوارتزي مغسول", "كسر وحبيبات رخام وحجر طبيعي متدرج", "بودرة حجر جيري وكوارتز ميكروني", "أكاسيد ألوان غير عضوية مقاومة للأشعة فوق البنفسجية", "مواد بوليمرية وإضافات عزل مائي (Sika-1 / Addibond 65)"),
            toolsNeeded = listOf("سقالات معدنية نمطية مطابقة للأمان", "بوشار فولاذي (شاكوش تسنين الحجر الصناعي)", "ماكينة طرطشة ميكانيكية وكمبروسر رش ضهارات", "أمشاط وشوك تخريش وتقسيم العراميس", "قدد ألومنيوم ثقيلة 3م وميزان خيط طويل 20م للواجهات", "قدة وأفّة وميزان ليزر وخيط", "مسطرين وبروة ومحارة ووعاء قياس"),
            executionSteps = listOf("1. شرب الواجهة والتأكيس الرأسي: إسقاط خيوط شواغيل رأسية من أعلى نقطة في روف المبنى حتى الرصيف لتوحيد سمك المحارة ومحاذاة الشرفات والبروزات المعمارية. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "2. الطرطشة المسمارية المشبعة بالأديبوند وعمل بؤج وأوتار الواجهة مع مراعاة أن تكون الأوتار غنية بالأسمنت ومستقيمة تماماً تحت القدة 3م. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "3. تنفيذ عراميس التمدد الأفقية والرأسية: تثبيت فليتات خشبية أو PVC كل 3 إلى 4 أمتار أفقياً وعند مناسيب البلاطات الخرسانية لتفريغ الإجهادات الحرارية ومنع حدوث شروخ عشوائية بالواجهات المرتفعة. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "4. فرد البطانة الخارجية بمونة أسمنتية غنية مضافاً إليها مانع نفاذية المياه (Waterproofing Admixture) ومسها وتخشينها لتكون قاعدة قوية للضهارة. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "5. تطبيق ضهارة الحجر الصناعي: فرد خلطة مكونة من أسمنت أبيض وبودرة حجر وكسر رخام ناعم وأكسيد اللون المطلوب بسماكة 8-10 مم، ثم تمشيطها وتركها لتتصلد 48 ساعة قبل البدء في دق البوشار. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "6. دق البوشار ودق العراميس: بعد تصلد ضهارة الحجر الصناعي، يتم دق السطح بانتظام باستخدام مطرقة البوشار المسننة لإزالة القشرة السطحية وإبراز حبيبات كسر الرخام وإعطاء مظهر الحجر الطبيعي المنحوت، مع تفريغ ونحت العراميس الغاطسة لتقسيم الواجهة لبلوكات منتظمة. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "7. تطبيق بياض الجرافيتو والواجهات الملونة: في حالة اختيار الجرافيتو، يتم فرد المعجون الإكريليكي الجاهز بالبروة ثم سحبه وتخشينه بالرابونة البلاستيكية في اتجاه رأسي أو دائري لإبراز العروق الكوارتزية المتجانسة. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "8. عزل وحماية الواجهة: دهان طبقة حماية شفافة طاردة للمياه (Silicone Water Repellent / Sikagard) لحماية الواجهة من امتصاص مياه الأمطار وعوامل التلوث البيئي والغبار. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]"),
            dimensionsAndSlopes = "المحارة تضبط مستوى التشطيب ولا تعوض اعوجاجًا كبيرًا بطبقة واحدة؛ السماكة القصوى واستواء السطح يحددهما نظام البياض ومواصفة المشروع.",
            mixesAndRatios = "لا تُعمّم جرعة الأديبوند على كل المونة؛ فرّق بين طرطشة الربط والبطانة والضهارة. المحارة الجاهزة تُخلط بالمياه المحددة دون إضافة رمل أو أسمنت.",
            technicalRequirements = listOf("تنفيذ سحقية وجلسات الشبابيك والكرانيش بميول واضحة للخارج مع عمل برطومة قطرة ماء غاطسة لمنع تسريب مياه الأمطار إلى داخل الشبابيك والمباني.", "حظر تنفيذ بياض الواجهات تحت أشعة الشمس المباشرة الحارقة في الصيف أو أثناء هبوب العواصف الترابية والأمطار.", "معالجة الواجهات بالرش بالمياه باستمرار لمدة 7 أيام متتالية صباحاً ومساءً. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]"),
            mepCoordination = "عمق علب الكهرباء والحلوق يُراجع على وجه المحارة النهائي؛ صوّر الخدمات قبل البياض ولا تسد فتحات الصيانة.",
            siteTips = listOf("ملاحظة تنفيذ: لتفادي ظهور فواصل اللحام والتوقف (Cold Joints) في بياض الواجهات والجرافيتو، لا توقف العمل في منتصف الحائط أبداً؛ يجب أن ينتهي العمل دائماً عند عرموس معماري غاطس أو عند زاوية المبنى، ويجب أن يعمل طاقم المبيضين بنظام السلسلة الرأسية المتصلة من أعلى السقالة إلى أسفلها دفعة واحدة.", "استخدم أكاسيد ألوان معدنية غير عضوية (Inorganic Oxides) كأكاسيد الحديد والكوبالت والكروم، وتجنب الألوان العضوية التي تبهت وتتغير تحت تأثير أشعة الشمس فوق البنفسجية بعد أشهر قليلة.", "جهز عينة تبين ملمس السطح المطلوب للدهان أو للصق البلاط.", "حافظ على رطوبة المعالجة دون إغراق السطح، واحمِ الواجهات من الشمس والرياح وقت التنفيذ."),
            commonMistakes = listOf("إهمال عمل عراميس وفواصل تمدد في الواجهات التي يزيد طولها عن 6 أمتار، مما يؤدي لظهور شروخ رأسية عشوائية حتمية بسبب التمدد والانكماش الحراري.", "دق البوشار على بياض الحجر الصناعي مبكراً قبل تمام تصلده، مما يقتلع كسر الرخام من جذوره ويحدث فجوات وحفراً مشوهة بالواجهة.", "استعمال مونة بدأت تشك ثم تليينها بمياه.", "غلق فاصل حركة بالمونة أو تركيب شبك مرتخٍ فوق فاصل مواد مختلفة."),
            qualityTests = listOf("فحص الرأسية الكاملة للواجهة بشواغيل خيط الإسقاط من الروف", "اختبار رش المياه بالخرطوم للتأكد من طرد مياه الأمطار وعمل الميول وبراطيم المياه", "فحص تجانس درجة اللون وعدم وجود بقع أو تعريج"),
            handoverCriteria = listOf("رأسية واستقامة كامل واجهة المبنى وتطابق خطوط الكرانيش والبانوهات على خيط واحد.", "تجانس دق البوشار أو ملمس الجرافيتو واللون على كامل مسطح الواجهة دون فواصل توقف.", "فعالية قطرات الميول وحماية جميع الفتحات والشبابيك من تسرب المياه."),
            codeReferences = listOf("نشرات أنظمة البياض المختارة ومواصفة المشروع؛ مواد مونة سيكا مصر: https://egy.sika.com/en/construction/cement-epoxy-mortars.html", "الرسومات والمواصفات المعتمدة للمشروع؛ لا يُنسب رقم للكود دون التحقق من البند والإصدار."),
            relatedMaterialIds = listOf("mat_portland_cement", "mat_addibond_65", "mat_sand_washed")
