        ExecutionStage(
            id = "stage_plaster_07",
            categoryId = 3,
            stageNumber = 7,
            titleAr = "الفحوصات الهندسية المتقدمة واستلامات المحارة واستلام القدة",
            objective = "إجراء بروتوكول الاستلام الهندسي الشامل لبياض المحارة وفق مواصفة المشروع وطرق التحقق المعتمدة قبل تسليم الحوائط لمراحل الدهانات أو السيراميك.",
            prerequisites = "انتهاء كامل أعمال المحارة وجفافها التام بعد انتهاء فترة المعالجة بالرش بالمياه (7 أيام على الأقل) ونظافة الموقع تماماً من المخلفات والسواقط.\nاختبار التغذية والصرف والكهرباء المخفية؛ استلام المباني والحلوق والعلب وتحديد الشرب وسمك التشطيب.",
            requiredMaterials = listOf("طباشير تعليم أو قلم ماركر عريض", "شريط لاصق لتحديد العيوب", "مطرقة خشبية أو بلاستيكية فحص خفيفة (Inspection Mallet)", "شريط قياس ليزري ودقيق"),
            toolsNeeded = listOf("قدة ألومنيوم مفرغة طول 3 أمتار وطول 2 متر مستقيمة الحواف بنسبة وفق نتيجة الاختبار", "ميزان ليزر متعدد الخطوط 360 درجة مع كاشف رقمي", "ميزان مياه عالي الدقة 120 سم وميزان خيط شاغول ثقيل 500 جم", "زاوية حديد صلب كبيرة 100 × 100 سم", "جهاز قياس رطوبة الحوائط الرقمي (Pinless Moisture Meter)", "قدة وأفّة وميزان ليزر وخيط", "مسطرين وبروة ومحارة ووعاء قياس"),
            executionSteps = listOf("1. اختبار استواء وقدة البياض (Straight-Edge Test): وضع قدة الألومنيوم بطول 3 أمتار على الحائط في عدة أوضاع ومستويات: أفقياً (في الأسفل والوسط والأعلى)، رأسياً (كل 1 متر على طول الحائط)، وقطرياً بزاوية 45 درجة (من الزوايا العلوية والسفلية). يتم فحص وجود أي فراغ نفاذ ضوء بين القدة والحائط، حيث يُشترط ألا يتعدى الفراغ 2 مم تحت قدة 3م، وألا يتعدى 1.5 مم تحت قدة 2م. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "2. اختبار الرأسية وميزان الشاغول (Plumbness Inspection): مطابقة رأسية كامل الحائط بميزان الخيط المتدلي من السقف وحتى مسافة 10 سم فوق الأرضية، ومطابقة خط الليزر الرأسي الأخضر مع الحائط؛ التفاوت المسموح في كامل ارتفاع الدور (حتى 3 أمتار) هو صفر إلى 2 مم كحد أقصى مطلق. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "3. اختبار التربيع وتعامد الأركان 90° (Squareness Test): وضع الزاوية الحديدية الكبيرة 100×100 سم في جميع أركان الغرف الأربعة؛ يجب أن تنطبق ساقا الزاوية انطباقاً تاماً على الحائطين دون أي فتحة أو فراغ في الطرفين. للغرف الكبيرة يتم تطبيق قاعدة فيثاغورس (3م - 4م - 5م) بشريط القياس الصلب لمطابقة أقطار الغرفة (تساوي القطرين X تماماً بنسبة خطأ صفر). [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "4. اختبار توازي الحوائط المتقابلة (Wall Parallelism): قياس المسافة الصافية بين الحائطين المتقابلين في الغرفة عند البداية وفي الوسط وعند النهاية؛ يجب أن تتطابق المسافات الثلاث بالمليمتر لتفادي وجود أي شطرة (سمكة) عند تركيب السيراميك أو الباركيه والفرش. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "5. اختبار التطبيل بالمطرقة (Hollow Sound Hammer Test): المرور بمطرقة الفحص البلاستيكية الخفيفة والنقر الخفيف المنتظم على كامل مسطح الحائط والزوايا والأكتاف وحول علب الكهرباء والكمرات؛ أي صوت طبلة أجوف ومكتوم يشير إلى انفصال طبقة المحارة عن المباني أو الخرسانة وتكوّن فراغ هوائي، ويتم فوراً تحديد المنطقة بالماركر لتكسيرها وإعادة معالجتها. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "6. اختبار التزهير والتمليح (Efflorescence Check): فحص خلو أسطح المحارة من أي بودرة بيضاء أو ترسبات أملاح تدل على استخدام مياه مالحة أو رمل غير مغسول أو وجود رطوبة مستمرة ترشح من الأرضيات أو مواسير السباكة. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]", "7. اختبار نسبة الرطوبة السطحية (Moisture Measurement): قياس رطوبة الحائط بجهاز المويستشر ميتر قبل السماح بالبدء في أعمال دهان السيلر والمعجون؛ يجب ألا تتعدى نسبة الرطوبة 4% إلى 5% لضمان عدم احتباس الرطوبة وتقشير الدهانات لاحقاً. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]"),
            dimensionsAndSlopes = "المحارة تضبط مستوى التشطيب ولا تعوض اعوجاجًا كبيرًا بطبقة واحدة؛ السماكة القصوى واستواء السطح يحددهما نظام البياض ومواصفة المشروع.",
            mixesAndRatios = "لا تُعمّم جرعة الأديبوند على كل المونة؛ فرّق بين طرطشة الربط والبطانة والضهارة. المحارة الجاهزة تُخلط بالمياه المحددة دون إضافة رمل أو أسمنت.",
            technicalRequirements = listOf("توقيع المهندس المشرف واستشاري الجودة على استمارة فحص واستلام البياض (Checklist & Inspection Request) قبل إعطاء الإذن ببدء أعمال السيراميك أو الدهانات.", "حظر التهاون في تطبيل المحارة حتى لو كانت المساحة صغيرة، لأن التطبيل يتسع تدريجياً مع الزمن ويهوي ويسقط تحت ثقل السيراميك أو الدهانات.", "مطابقة علب الكهرباء الماجيك لتكون على وش المحارة تماماً دون غطس يزيد عن 2 مم ودون أي بروز نهائياً. [القيم الواردة مثال يتأكد من ملاءمته في التصميم ودليل المنتج؛ القبول وفق المواصفة المعتمدة.]"),
            mepCoordination = "عمق علب الكهرباء والحلوق يُراجع على وجه المحارة النهائي؛ صوّر الخدمات قبل البياض ولا تسد فتحات الصيانة.",
            siteTips = listOf("ملاحظة تنفيذ: عند استلام تربيع الغرف في الشقق المفروشة بالباركيه أو السيراميك اللامع، اختبر أقطار الغرفة بشريط القياس الليزري (Diagonal Cross Measurement)؛ إذا تساوى القطران بالمليمتر فاعلم أن تبليط الأرضيات سيبدأ وينتهي ببلاطات كاملة دون أي زوايا مسلوبة أو سمكات مشوهة في الأركان.", "علم على الأجزاء المطبلة فوراً بالطباشير الأحمر على شكل مربع أو دائرة، واطلب من المقاول تكسيرها أمامك حتى الوصول إلى السطح الخرساني الصلب وليس مجرد كشط سطحي.", "جهز عينة تبين ملمس السطح المطلوب للدهان أو للصق البلاط.", "حافظ على رطوبة المعالجة دون إغراق السطح، واحمِ الواجهات من الشمس والرياح وقت التنفيذ."),
